const todayISO=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const state={filters:{area:'All Dhaka',sport:'Football',date:todayISO(),time:'Any time',query:'',min:'',max:'',sort:'Recommended'},view:'list',venue:null,slot:0,date:0,auth:'login',favorites:loadFavorites(),user:loadCurrentUser(),returnTo:'/',pendingBookingVenue:null};

function loadAccounts(){try{return JSON.parse(localStorage.getItem("turfmate:accounts")||"[]")}catch{return[]}}
function loadCurrentUser(){try{const id=localStorage.getItem("turfmate:session");const a=loadAccounts().find(x=>x.id===id);return a?{id:a.id,name:a.name,email:a.email,username:a.username,phone:a.phone||""}:null}catch{return null}}
function loadRecords(key){try{const v=JSON.parse(localStorage.getItem(key)||"[]");return Array.isArray(v)?v:[]}catch{return[]}}
function saveRecord(key,record){const rows=loadRecords(key);rows.unshift(record);localStorage.setItem(key,JSON.stringify(rows));return record}
function bytesToBase64(bytes){let binary="";for(const byte of bytes)binary+=String.fromCharCode(byte);return btoa(binary)}
function base64ToBytes(value){return Uint8Array.from(atob(value),c=>c.charCodeAt(0))}
async function derivePassword(password,salt){const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(password),"PBKDF2",false,["deriveBits"]);const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt:salt,iterations:160000,hash:"SHA-256"},key,256);return bytesToBase64(new Uint8Array(bits))}
function secureEqual(a,b){if(typeof a!=="string"||typeof b!=="string"||a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i++)diff|=a.charCodeAt(i)^b.charCodeAt(i);return diff===0}
function syncHeaderAuth(){document.querySelectorAll('[data-action="open-auth"],[data-action="account-menu"]').forEach(button=>{button.dataset.action=state.user?"account-menu":"open-auth";button.innerHTML=state.user?"<span>"+esc(state.user.name.split(" ")[0])+"</span> <span>↗</span>":(button.closest(".mobile-nav")?"Log in / Sign up":"Log in <span>↗</span>")})}
function authPage(mode){
 const signup=mode==="register";
 const fields=signup
 ? '<div class="auth-field"><label for="auth-name">Full name</label><input id="auth-name" name="name" autocomplete="name" placeholder="Your full name" required minlength="2"></div><div class="auth-field"><label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required></div><div class="auth-field"><label for="auth-username">Username</label><input id="auth-username" name="username" autocomplete="username" placeholder="e.g. atif_player" required minlength="3" maxlength="20" pattern="[A-Za-z0-9_]{3,20}"><small>3–20 characters. Letters, numbers and underscores.</small></div><div class="auth-field"><label for="auth-phone">Mobile number <span>(optional)</span></label><input id="auth-phone" name="phone" autocomplete="tel" inputmode="tel" placeholder="01XXXXXXXXX"></div><div class="auth-field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="new-password" placeholder="At least 8 characters" required minlength="8"></div><div class="auth-field"><label for="auth-confirm">Confirm password</label><input id="auth-confirm" name="confirm" type="password" autocomplete="new-password" placeholder="Enter the password again" required minlength="8"></div>'
 : '<div class="auth-field"><label for="auth-identifier">Email or username</label><input id="auth-identifier" name="identifier" autocomplete="username" placeholder="Enter your email or username" required></div><div class="auth-field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="current-password" placeholder="Enter your password" required></div>';
 return '<section class="auth-page"><div class="auth-visual"><div class="auth-visual-top"><a class="brand brand-footer" href="#/"><img src="assets/turfmate-mark.svg" alt=""><span>turf<span class="brand-light">mate</span><i>.</i></span></a><span class="auth-live"><i class="live-dot"></i> DHAKA · BUILT FOR THE GAME</span></div><div class="auth-visual-copy"><span class="eyebrow">YOUR GAME. YOUR PEOPLE.</span><h2>Make every<br>match <em>count.</em></h2><p>Find your pitch, save your favourite venues and keep your match plans together.</p></div><div class="auth-visual-foot"><span>LESS PLANNING. MORE PLAYING.</span><span>01 — TURFMATE PLAYER ACCESS</span></div></div><div class="auth-panel"><div class="auth-panel-inner"><span class="eyebrow">'+(signup?"CREATE YOUR ACCOUNT":"PLAYER ACCESS")+'</span><h1>'+(signup?"Join the game.":"Welcome back.")+'</h1><p class="auth-intro">'+(signup?"Create your TurfMate player profile and keep your football plans in one place.":"Log in to access your saved pitches and booking enquiries.")+'</p><form class="auth-form auth-page-form" id="auth-form" data-mode="'+(signup?"register":"login")+'">'+fields+'<p class="auth-error" id="auth-error" role="alert" hidden></p><button class="btn btn-dark auth-submit" type="submit">'+(signup?"Create my account":"Log in to TurfMate")+' <span>↗</span></button></form><p class="auth-switch">'+(signup?"Already have an account?":"New to TurfMate?")+' <a href="#/'+(signup?"login":"register")+'">'+(signup?"Log in":"Create an account")+'</a></p><p class="auth-local-note"><strong>Prototype account:</strong> details are stored only in this browser. This is not production authentication; do not reuse an important password.</p></div></div></section>';
}
function accountModal(){return '<section class="modal-card account-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h3 id="modal-title">Your TurfMate account</h3><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body"><div class="account-identity"><span class="account-avatar">'+esc((state.user?.name||"T").charAt(0).toUpperCase())+'</span><div><strong>'+esc(state.user?.name||"Player")+'</strong><span>'+esc(state.user?.email||"")+'</span></div></div><div class="account-links"><a href="#/bookings">My booking enquiries ↗</a><a href="#/saved">Saved pitches ↗</a></div><button class="btn btn-dark" style="width:100%" data-action="logout">Log out</button><p class="disclaimer">Your prototype account and saved data are stored on this device only.</p></div></section>'}
function bookingRequestModal(id){const v=venues.find(x=>x.id===id);if(!v)return "";return '<section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h3 id="modal-title">Send a booking enquiry</h3><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body"><div class="modal-venue"><div class="modal-venue-art" style="'+(v.image?"background-image:url('"+esc(v.image)+"')":'')+'"></div><div><h2>'+esc(v.name)+'</h2><p>'+esc(v.area)+', Dhaka · Not live-connected</p></div></div><form class="auth-form booking-request-form" id="booking-request-form" data-venue-id="'+esc(v.id)+'"><div><label for="request-date">Preferred date</label><input id="request-date" name="date" type="date" min="'+todayISO()+'" value="'+esc(state.filters.date||todayISO())+'" required></div><div><label for="request-time">Preferred time</label><select id="request-time" name="time" required><option value="">Choose a time</option><option>Morning</option><option>Afternoon</option><option>Evening</option><option>Night</option></select></div><div><label for="request-players">Players / team size</label><select id="request-players" name="players"><option>5–7 players</option><option>8–10 players</option><option>11–14 players</option><option>15+ players</option></select></div><div><label for="request-phone">Contact number</label><input id="request-phone" name="phone" inputmode="tel" placeholder="01XXXXXXXXX" value="'+esc(state.user?.phone||"")+'" required></div><button class="btn btn-dark" type="submit">Save my enquiry ↗</button></form><p class="disclaimer">This saves an enquiry on this device only. It does not contact the venue or confirm a reservation. Use the official venue link for a real booking.</p></div></section>'}
function tournamentInterestModal(eventName){return '<section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h3 id="modal-title">Tournament interest</h3><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body"><p class="muted">Share your details for <strong>'+esc(eventName||"this event")+'</strong>.</p><form class="auth-form" id="tournament-interest-form"><input type="hidden" name="event" value="'+esc(eventName||"TurfMate event")+'"><div><label for="interest-name">Your name</label><input id="interest-name" name="name" value="'+esc(state.user?.name||"")+'" required></div><div><label for="interest-team">Team name</label><input id="interest-team" name="team" placeholder="Your squad name" required></div><div><label for="interest-email">Email</label><input id="interest-email" name="email" type="email" value="'+esc(state.user?.email||"")+'" required></div><div><label for="interest-phone">Phone</label><input id="interest-phone" name="phone" inputmode="tel" value="'+esc(state.user?.phone||"")+'" required></div><button class="btn btn-dark" type="submit">Save interest ↗</button></form><p class="disclaimer">Prototype only. Your interest is saved on this browser and is not sent to an organiser.</p></div></section>'}

function loadFavorites(){try{return new Set(JSON.parse(localStorage.getItem('turfmate:favorites')||'[]'))}catch{return new Set()}}
function saveFavorites(){try{localStorage.setItem('turfmate:favorites',JSON.stringify([...state.favorites]))}catch{}}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(v){return Number(v)>0?'৳'+Number(v).toLocaleString('en-BD'):'Price not published'}
function dateObj(offset){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+offset);return d}
function dateLabel(offset){const d=dateObj(offset);return {day:d.toLocaleDateString('en-US',{weekday:'short'}),date:d.getDate(),month:d.toLocaleDateString('en-US',{month:'short'})}}
function art(label='PITCH / DHAKA',v){return `<div class="venue-art ${v?.image?'has-photo':''}" aria-hidden="true">${v?.image?`<img src="${esc(v.image)}" alt="" loading="lazy" onerror="this.remove()">`:''}<span class="art-lines"></span><span class="art-label">${esc(label)}</span><span class="venue-badge">${esc(v?.label||'TurfMate pick')}</span>${v?`<button class="favorite ${state.favorites.has(v.id)?'saved':''}" data-action="favorite" data-id="${v.id}" aria-label="${state.favorites.has(v.id)?'Remove':'Save'} ${esc(v.name)}">${state.favorites.has(v.id)?'♥':'♡'}</button>`:''}</div>`}
function card(v){
 const image=v.image?'<img src="'+esc(v.image)+'" alt="'+esc(v.name)+' venue" loading="lazy" onerror="this.remove()">':'';
 const price=v.price>0?(v.priceNote||money(v.price)+' / 90 min'):'Contact venue for pricing';
 return '<article class="venue-card premium-venue-card" data-open-venue="'+esc(v.id)+'"><div class="venue-card-media">'+image+'<span class="venue-card-kicker">TURFMATE VENUE PROFILE</span><button class="favorite '+(state.favorites.has(v.id)?'saved':'')+'" data-action="favorite" data-id="'+esc(v.id)+'" aria-label="'+(state.favorites.has(v.id)?'Remove':'Save')+' '+esc(v.name)+'">'+(state.favorites.has(v.id)?'♥':'♡')+'</button><span class="venue-card-area">'+esc(v.area)+'</span></div><div class="venue-info"><div class="venue-top"><div><h3>'+esc(v.name)+'</h3><div class="venue-area">⌖ '+esc(v.address)+'</div></div></div><p class="venue-description">'+esc(v.description)+'</p><div class="tags">'+v.sports.map(s=>'<span class="tag">'+esc(s)+'</span>').join('')+v.amenities.slice(0,2).map(s=>'<span class="tag">'+esc(s)+'</span>').join('')+'</div><div class="venue-card-bottom"><div class="venue-price-block"><small>'+(v.price>0?'PUBLISHED PRICE':'PRICING')+'</small><strong>'+esc(price)+'</strong></div><div class="venue-card-links"><a href="'+mapsUrl(v)+'" target="_blank" rel="noopener noreferrer">Map ↗</a><a href="'+esc(v.website)+'" target="_blank" rel="noopener noreferrer">Official site ↗</a></div></div><button class="venue-details-button" data-action="view-venue" data-id="'+esc(v.id)+'">View venue details <span>↗</span></button></div></article>';
}
