    {id:'futsal',name:'Dhaka Futsal Cup',format:'5v5',area:'Bashundhara R/A',window:'Dates to be announced',teams:'12 teams',status:'Coming soon',tone:'futsal',description:'Quick transitions, tight spaces and non-stop action under the lights.'},
    {id:'weekend',name:'Weekend League',format:'7v7',area:'Aftabnagar',window:'Dates to be announced',teams:'8 teams',status:'Registration open',tone:'league',description:'A community-first league for regular teams and new challengers.'}
